if ($route === 'settings' && isset($_POST['admin_site_logo_ajax'])) {
    header('Content-Type: application/json; charset=utf-8');

    if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
        http_response_code(403);
        echo json_encode([
            'ok' => false,
            'message' => admin_t($messages, 'settings_site_logo_csrf_error', 'Your session expired. Refresh the page and try again.'),
        ]);
        exit;
    }

    if (!schema_object_exists($db, 'app_settings')) {
        http_response_code(500);
        echo json_encode([
            'ok' => false,
            'message' => admin_t($messages, 'settings_site_logo_upload_error', 'Unable to upload the logo right now.'),
        ]);
        exit;
    }

    $logoAction = trim((string)($_POST['logo_action'] ?? ''));
    $currentLogoUrl = trim((string)($appSettings['site_logo_url'] ?? ''));

    if ($logoAction === 'upload') {
        $uploadedLogoUrl = admin_site_logo_public_path($_FILES['site_logo_file'] ?? [], (int)$adminUser['id']);
        if ($uploadedLogoUrl === null) {
            http_response_code(422);
            echo json_encode([
                'ok' => false,
                'message' => admin_t($messages, 'settings_site_logo_upload_error', 'Unable to upload the logo right now.'),
            ]);
            exit;
        }

        $updated = $db->update_using_id(['site_logo_url'], [$uploadedLogoUrl], 'app_settings', 1);
        if (!$updated) {
            admin_delete_site_logo_file($uploadedLogoUrl);
            http_response_code(500);
            echo json_encode([
                'ok' => false,
                'message' => admin_t($messages, 'settings_site_logo_upload_error', 'Unable to upload the logo right now.'),
            ]);
            exit;
        }

        if ($currentLogoUrl !== '' && $currentLogoUrl !== $uploadedLogoUrl) {
            admin_delete_site_logo_file($currentLogoUrl);
        }

        echo json_encode([
            'ok' => true,
            'url' => $uploadedLogoUrl,
            'message' => admin_t($messages, 'settings_site_logo_upload_success', 'Logo uploaded successfully.'),
        ]);
        exit;
    }

    if ($logoAction === 'remove') {
        $updated = $db->update_using_id(['site_logo_url'], [null], 'app_settings', 1);
        if (!$updated) {
            http_response_code(500);
            echo json_encode([
                'ok' => false,
                'message' => admin_t($messages, 'settings_site_logo_remove_error', 'Unable to remove the logo right now.'),
            ]);
            exit;
        }

        if ($currentLogoUrl !== '') {
            admin_delete_site_logo_file($currentLogoUrl);
        }

        echo json_encode([
            'ok' => true,
            'url' => '',
            'message' => admin_t($messages, 'settings_site_logo_remove_success', 'Logo removed.'),
        ]);
        exit;
    }

    if ($logoAction === 'set_url') {
        $newLogoUrl = trim((string)($_POST['site_logo_url'] ?? ''));
        if ($newLogoUrl !== '' && filter_var($newLogoUrl, FILTER_VALIDATE_URL) === false) {
            http_response_code(422);
            echo json_encode([
                'ok' => false,
                'message' => admin_t($messages, 'settings_site_logo_url_invalid', 'Provide a valid direct image URL.'),
            ]);
            exit;
        }

        $updated = $db->update_using_id(['site_logo_url'], [$newLogoUrl !== '' ? $newLogoUrl : null], 'app_settings', 1);
        if (!$updated) {
            http_response_code(500);
            echo json_encode([
                'ok' => false,
                'message' => admin_t($messages, 'settings_site_logo_upload_error', 'Unable to upload the logo right now.'),
            ]);
            exit;
        }

        if ($currentLogoUrl !== '' && $currentLogoUrl !== $newLogoUrl) {
            admin_delete_site_logo_file($currentLogoUrl);
        }

        echo json_encode([
            'ok' => true,
            'url' => $newLogoUrl,
            'message' => admin_t($messages, 'settings_site_logo_url_saved', 'Logo URL has been updated.'),
        ]);
        exit;
    }

    http_response_code(400);
    echo json_encode([
        'ok' => false,
        'message' => admin_t($messages, 'settings_site_logo_upload_error', 'Unable to upload the logo right now.'),
    ]);
    exit;
}

if ($route === 'products' && isset($_POST['admin_product_provider_logo_ajax'])) {
    header('Content-Type: application/json; charset=utf-8');

    if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
        http_response_code(403);
        echo json_encode([
            'ok' => false,
            'message' => admin_t($messages, 'product_provider_logo_csrf_error', 'Your session expired. Refresh the page and try again.'),
        ]);
        exit;
    }

    $logoAction = trim((string)($_POST['logo_action'] ?? ''));
    $currentLogoUrl = trim((string)($_POST['current_logo_url'] ?? ''));
    $providerId = isset($_POST['provider_id']) ? (int)$_POST['provider_id'] : 0;
    $persistToProvider = $providerId > 0;
    $persistedLogoUrl = '';

    if ($persistToProvider) {
        $providerRow = admin_product_provider_find($db, $providerId);
        if (!is_array($providerRow) || empty($providerRow['id'])) {
            http_response_code(404);
            echo json_encode([
                'ok' => false,
                'message' => admin_t($messages, 'product_provider_not_found', 'Provider not found.'),
            ]);
            exit;
        }
        $persistedLogoUrl = trim((string)($providerRow['logo_url'] ?? ''));
    }

    if ($logoAction === 'upload') {
        $uploadedLogoUrl = admin_product_provider_logo_public_path($_FILES['provider_logo_file'] ?? [], (int)$adminUser['id']);
        if ($uploadedLogoUrl === null) {
            http_response_code(422);
            echo json_encode([
                'ok' => false,
                'message' => admin_t($messages, 'product_provider_logo_upload_error', 'Unable to upload the provider logo right now.'),
            ]);
            exit;
        }

        if ($persistToProvider) {
            $updated = $db->update_using_id(['logo_url'], [$uploadedLogoUrl], 'product_providers', $providerId);
            if (!$updated) {
                admin_delete_product_provider_logo_file($uploadedLogoUrl);
                http_response_code(500);
                echo json_encode([
                    'ok' => false,
                    'message' => admin_t($messages, 'product_provider_logo_upload_error', 'Unable to upload the provider logo right now.'),
                ]);
                exit;
            }
        }

        $previousLogoToDelete = $persistToProvider ? $persistedLogoUrl : $currentLogoUrl;
        if ($previousLogoToDelete !== '' && $previousLogoToDelete !== $uploadedLogoUrl) {
            admin_delete_product_provider_logo_file($previousLogoToDelete);
        }

        echo json_encode([
            'ok' => true,
            'url' => $uploadedLogoUrl,
            'message' => admin_t($messages, 'product_provider_logo_upload_success', 'Provider logo uploaded successfully.'),
        ]);
        exit;
    }

    if ($logoAction === 'remove') {
        if ($persistToProvider) {
            $updated = $db->update_using_id(['logo_url'], [null], 'product_providers', $providerId);
            if (!$updated) {
                http_response_code(500);
                echo json_encode([
                    'ok' => false,
                    'message' => admin_t($messages, 'product_provider_logo_remove_error', 'Unable to remove the provider logo right now.'),
                ]);
                exit;
            }
        }

        $previousLogoToDelete = $persistToProvider ? $persistedLogoUrl : $currentLogoUrl;
        if ($previousLogoToDelete !== '') {
            admin_delete_product_provider_logo_file($previousLogoToDelete);
        }

        echo json_encode([
            'ok' => true,
            'url' => '',
            'message' => admin_t($messages, 'product_provider_logo_remove_success', 'Provider logo removed.'),
        ]);
        exit;
    }

    http_response_code(400);
    echo json_encode([
        'ok' => false,
        'message' => admin_t($messages, 'product_provider_logo_upload_error', 'Unable to upload the provider logo right now.'),
    ]);
    exit;
}

if ($route === 'settings' && isset($_POST['admin_save_smtp_settings'])) {
