if ($route === 'settings' && isset($_POST['admin_download_database_backup'])) {
    if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
        if ($isAjaxRequest) {
            header('Content-Type: application/json; charset=utf-8');
            echo json_encode([
                'ok' => false,
                'message' => admin_t($messages, 'login_error', 'Login failed. Check your credentials.'),
            ]);
            exit;
        }

        $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
        $pageAlertType = 'danger';
    } else {
        ob_start();
        $backupResult = app_generate_database_sql_backup_file($db);
        $unexpectedOutput = trim((string)ob_get_clean());
        $manualDatabaseBackupInfo = app_database_backup_latest_info();

        if ($unexpectedOutput !== '' && empty($backupResult['ok'])) {
            $backupResult['message'] = trim((string)($backupResult['message'] ?? '') . ' ' . $unexpectedOutput);
        }

        if ($isAjaxRequest) {
            $backupPayload = null;
            if (!empty($backupResult['ok']) && !empty($manualDatabaseBackupInfo['exists'])) {
                $downloadUrl = '/admin/?page=settings&download_latest_database_backup=1&_csrf=' . rawurlencode($csrfToken);
                $generatedAt = trim((string)($manualDatabaseBackupInfo['generated_at'] ?? ''));
                $backupPayload = [
                    'name' => (string)($manualDatabaseBackupInfo['download_name'] ?? 'latest-database-backup.sql'),
                    'generated_at' => $generatedAt,
                    'generated_at_label' => $generatedAt !== '' ? date('d.m.Y H:i:s', strtotime($generatedAt)) : '',
                    'size_label' => (string)($manualDatabaseBackupInfo['size_label'] ?? '0 B'),
                    'download_url' => $downloadUrl,
                ];
            }

            header('Content-Type: application/json; charset=utf-8');
            echo json_encode([
                'ok' => !empty($backupResult['ok']),
                'message' => (string)($backupResult['message'] ?? admin_t($messages, 'settings_database_backup_error', 'Unable to create the SQL backup.')),
                'backup' => $backupPayload,
            ]);
            exit;
        }

        if (!empty($backupResult['ok'])) {
            $pageAlert = (string)($backupResult['message'] ?? admin_t($messages, 'settings_database_backup_success', 'SQL backup created successfully.'));
            $pageAlertType = 'success';
        } else {
            $pageAlert = (string)($backupResult['message'] ?? admin_t($messages, 'settings_database_backup_error', 'Unable to create the SQL backup.'));
            $pageAlertType = 'danger';
        }
    }
}

if ($route === 'settings' && isset($_POST['admin_panel_close_review'])) {
    if ($settingsAdminMode && admin_user_can_access_route($adminUser,'settings') && admin_csrf_is_valid($_POST['_csrf']??'')) {
        try {
            app_panel_tiers_close_review($db,(int)filter_var($_POST['admin_panel_close_review'],FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]));
            $pageAlert=admin_panel_tiers_text('review_closed');$pageAlertType='success';
        } catch (DomainException $e) {$pageAlert=admin_panel_tiers_text($e->getMessage());$pageAlertType='warning';}
        catch (Throwable $e) {$pageAlert=admin_panel_tiers_text('storage');$pageAlertType='danger';}
    } else {$pageAlert=admin_panel_tiers_text('session');$pageAlertType='danger';}
}

if ($route === 'settings' && isset($_POST['admin_save_panel_subscription_settings'])) {
    if (!$settingsAdminMode || !admin_user_can_access_route($adminUser, 'settings') || !admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
        $pageAlert = admin_panel_tiers_text('session'); $pageAlertType = 'danger';
    } else {
        try {
            foreach ($_POST as $postedValue) if (!is_string($postedValue)) throw new DomainException('storage');
            $date = trim((string)($_POST['admin_panel_subscription_paid_until'] ?? ''));
            $url = trim((string)($_POST['admin_panel_subscription_renewal_url'] ?? ''));
            if ($date !== '' && (!preg_match('/^(\d{4})-(\d{2})-(\d{2})$/D', $date, $parts) || !checkdate((int)$parts[2],(int)$parts[3],(int)$parts[1]))) throw new DomainException('settings_panel_subscription_date_invalid');
            if ($url !== '' && (!filter_var($url,FILTER_VALIDATE_URL) || !in_array(strtolower((string)parse_url($url,PHP_URL_SCHEME)),['http','https'],true))) throw new DomainException('settings_panel_subscription_url_invalid');
            app_panel_tiers_save_config($db,$_POST,$adminDefaultCurrencyCode,['date'=>$date,'url'=>$url]);
            $appSettings=admin_app_settings($db);$panelTiersConfig=app_panel_tiers_config($db);
            $pageAlert=admin_t($messages,'settings_panel_subscription_saved','Admin panel subscription settings have been saved.');$pageAlertType='success';
        } catch (DomainException $e) {
            $pageAlert=isset($messages[$e->getMessage()])?admin_t($messages,$e->getMessage(),$e->getMessage()):admin_panel_tiers_text($e->getMessage());$pageAlertType='danger';
        } catch (Throwable $e) {$pageAlert=admin_panel_tiers_text('storage');$pageAlertType='danger';}
    }
}

if ($route === 'settings' && isset($_POST['admin_run_sql_import'])) {
    $sqlImportFormState = trim((string)($_POST['sql_import_code'] ?? ''));

    if (!$settingsAdminMode) {
        $pageAlert = admin_t($messages, 'settings_admin_mode_required', 'This action is available only in admin mode: /admin/?page=settings&admin=true.');
        $pageAlertType = 'danger';
    } elseif (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
        $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
        $pageAlertType = 'danger';
    } else {
        $sqlImportResult = admin_execute_sql_import($db, $sqlImportFormState);
        $executed = (int)($sqlImportResult['executed'] ?? 0);
        $skipped = (int)($sqlImportResult['skipped'] ?? 0);
        $details = (array)($sqlImportResult['details'] ?? []);
        $pageAlertType = !empty($sqlImportResult['ok']) ? 'success' : 'danger';
        $pageAlert = (string)($sqlImportResult['message'] ?? admin_t($messages, 'settings_sql_import_error', 'Unable to execute SQL import.'));
        $pageAlertHtml = admin_e($pageAlert)
            . '<br>' . admin_e(admin_t($messages, 'settings_sql_import_executed', 'Executed statements')) . ': <strong>' . admin_e((string)$executed) . '</strong>'
            . ' / ' . admin_e(admin_t($messages, 'settings_sql_import_skipped', 'Skipped statements')) . ': <strong>' . admin_e((string)$skipped) . '</strong>';

        if ($details !== []) {
            $pageAlertHtml .= '<ul class="mb-0 mt-2">';
            foreach (array_slice($details, 0, 5) as $detail) {
                $pageAlertHtml .= '<li>' . admin_e((string)$detail) . '</li>';
            }
            $pageAlertHtml .= '</ul>';
        }

        if (!empty($sqlImportResult['ok'])) {
            $sqlImportFormState = '';
        }
    }
}

