if ($route === 'cryptocurrencies') {
    $cryptoAssetEditorId = isset($_GET['edit_asset']) ? (int)$_GET['edit_asset'] : 0;

    if (isset($_POST['admin_save_crypto_asset'])) {
        $cryptoAssetEditorId = (int)($_POST['crypto_asset_id'] ?? 0);
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $saveResult = admin_save_crypto_asset($db, $cryptoAssetEditorId, $_POST);
            $pageAlert = (string)($saveResult['message'] ?? '');
            $pageAlertType = !empty($saveResult['ok']) ? 'success' : 'danger';
        }
    }

    $cryptoAssetRows = admin_refresh_crypto_asset_rates($db, $adminDefaultCurrencyCode, 900, [], true);
    if (!$cryptoAssetRows) {
        $cryptoAssetRows = admin_crypto_asset_rows($db, false);
    }
    if ($cryptoAssetEditorId > 0) {
        $cryptoAssetEditor = admin_crypto_asset_find($db, $cryptoAssetEditorId);
        if (!$cryptoAssetEditor) {
            $cryptoAssetEditorId = 0;
        }
    }
}

if ($route === 'news') {
    $newsEditorId = isset($_GET['edit_news']) ? (int)($_GET['edit_news']) : 0;
    $newsShowCreate = (string)($_GET['view'] ?? '') === 'create';
    $newsListPage = max(1, (int)($_GET['news_list_page'] ?? $_POST['news_list_page'] ?? 1));
    $newsListTotal = admin_news_count($db);
    $newsListTotalPages = max(1, (int)ceil($newsListTotal / $newsListPerPage));
    if ($newsListPage > $newsListTotalPages) {
        $newsListPage = $newsListTotalPages;
    }

    if (isset($_POST['admin_create_news'])) {
        $newsShowCreate = true;
        $newsListPage = max(1, (int)($_POST['news_list_page'] ?? $newsListPage));
        $newsFormState = [
            'title' => trim((string)($_POST['title'] ?? '')),
            'slug' => trim((string)($_POST['slug'] ?? '')),
            'body' => trim((string)($_POST['body'] ?? '')),
            'visibility' => strtolower(trim((string)($_POST['visibility'] ?? 'client'))),
            'is_active' => isset($_POST['is_active']) && (string)$_POST['is_active'] === '1' ? 1 : 0,
            'published_at' => admin_normalize_datetime_input($_POST['published_at'] ?? null) ?? date('Y-m-d H:i:s'),
        ];

        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $createResult = admin_create_news($db, $_POST);
            if (!empty($createResult['ok']) && !empty($createResult['news_id'])) {
                header('Location: /admin/?page=news&edit_news=' . (int)$createResult['news_id'] . '&news_list_page=' . $newsListPage . '&created_news=1');
                exit;
            }

            $pageAlert = (string)($createResult['message'] ?? admin_t($messages, 'news_create_error', 'Unable to create news post.'));
            $pageAlertType = 'danger';
        }
    }

    if (isset($_POST['admin_save_news'])) {
        $newsEditorId = (int)($_POST['news_id'] ?? 0);
        $newsListPage = max(1, (int)($_POST['news_list_page'] ?? $newsListPage));
        $newsFormState = [
            'title' => trim((string)($_POST['title'] ?? '')),
            'slug' => trim((string)($_POST['slug'] ?? '')),
            'body' => trim((string)($_POST['body'] ?? '')),
            'visibility' => strtolower(trim((string)($_POST['visibility'] ?? 'client'))),
            'is_active' => isset($_POST['is_active']) && (string)$_POST['is_active'] === '1' ? 1 : 0,
            'published_at' => admin_normalize_datetime_input($_POST['published_at'] ?? null) ?? date('Y-m-d H:i:s'),
        ];

        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $saveResult = admin_save_news($db, $newsEditorId, $_POST);
            if (!empty($saveResult['ok'])) {
                header('Location: /admin/?page=news&edit_news=' . $newsEditorId . '&news_list_page=' . $newsListPage . '&saved_news=1');
                exit;
            }

            $pageAlert = (string)($saveResult['message'] ?? admin_t($messages, 'news_save_error', 'Unable to save news post.'));
            $pageAlertType = 'danger';
        }
    }

    if (isset($_POST['admin_delete_news'])) {
        $newsEditorId = (int)($_POST['news_id'] ?? 0);
        $newsListPage = max(1, (int)($_POST['news_list_page'] ?? $newsListPage));

        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $deleteResult = admin_delete_news($db, $newsEditorId);
            if (!empty($deleteResult['ok'])) {
                header('Location: /admin/?page=news&news_list_page=' . $newsListPage . '&deleted_news=1');
                exit;
            }

            $pageAlert = (string)($deleteResult['message'] ?? admin_t($messages, 'news_delete_error', 'Unable to delete news post.'));
            $pageAlertType = 'danger';
        }
    }

    if ($newsEditorId > 0) {
        $newsEditor = admin_news_find($db, $newsEditorId);
        if (!$newsEditor) {
            $newsEditorId = 0;
        } elseif (isset($_POST['admin_save_news'])) {
            $newsEditor = array_merge($newsEditor, $newsFormState);
        }
    }
}

if ($route === 'crypto-wallets') {
    $walletCreateMode = isset($_GET['new_wallet']) && (int)$_GET['new_wallet'] === 1;
    $walletEditorId = isset($_GET['edit_wallet']) ? (int)$_GET['edit_wallet'] : 0;
    $walletFilterWalletId = isset($_GET['wallet_id']) ? (int)$_GET['wallet_id'] : 0;
    $walletListPage = max(1, (int)($_GET['wallet_list_page'] ?? 1));
    $walletGlobalTotal = admin_crypto_wallet_count_filtered($db, 0);
    $walletOnboardingVideoRows = $walletGlobalTotal <= 0
        ? admin_help_video_rows_by_ids($db, [15, 8, 6, 7, 10])
        : [];
    $walletListTotal = admin_crypto_wallet_count_filtered($db, $walletFilterWalletId);
    $walletListTotalPages = max(1, (int)ceil($walletListTotal / $walletListPerPage));
    if ($walletListPage > $walletListTotalPages) {
        $walletListPage = $walletListTotalPages;
    }
    if (isset($_GET['created_wallet']) && (int)$_GET['created_wallet'] === 1) {
        $pageAlert = admin_t($messages, 'wallet_create_success', 'Wallet address added successfully.');
        $pageAlertType = 'success';
    }

    if (isset($_POST['admin_save_crypto_wallet'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $walletEditorId = (int)($_POST['wallet_id'] ?? 0);
            $walletListPage = max(1, (int)($_POST['wallet_list_page'] ?? $walletListPage));
            $saveResult = admin_save_crypto_wallet($db, $walletEditorId, $_POST, (int)$adminUser['id'], $requestIp);
            if (!empty($saveResult['ok']) && $walletEditorId <= 0 && !empty($saveResult['wallet_id'])) {
                header('Location: /admin/?page=crypto-wallets&wallet_list_page=' . $walletListPage . '&edit_wallet=' . (int)$saveResult['wallet_id'] . '&created_wallet=1');
                exit;
            }
            $pageAlert = !empty($saveResult['ok'])
                ? admin_t($messages, 'wallet_save_success', 'Wallet saved successfully.')
                : ((string)($saveResult['message'] ?? '') !== ''
                    ? (string)$saveResult['message']
                    : admin_t($messages, 'wallet_save_error', 'Unable to save wallet.'));
            $pageAlertType = !empty($saveResult['ok']) ? 'success' : 'danger';
        }
    }

    if (isset($_POST['admin_assign_crypto_wallet_customer'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $walletEditorId = (int)($_POST['wallet_id'] ?? 0);
            $walletListPage = max(1, (int)($_POST['wallet_list_page'] ?? $walletListPage));
            $assignCustomerId = (int)($_POST['assignment_customer_id'] ?? 0);
            $assignResult = admin_assign_crypto_wallet_customer($db, $walletEditorId, $assignCustomerId, (int)$adminUser['id'], $appSettings, $requestIp);
            $pageAlert = (string)($assignResult['message'] ?? '');
            $pageAlertType = !empty($assignResult['ok']) ? 'success' : 'danger';
        }
    }

    if (isset($_POST['admin_remove_crypto_wallet_assignment'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $walletEditorId = (int)($_POST['wallet_id'] ?? 0);
            $walletListPage = max(1, (int)($_POST['wallet_list_page'] ?? $walletListPage));
            $assignmentId = (int)($_POST['admin_remove_crypto_wallet_assignment'] ?? 0);
            $removeResult = admin_remove_crypto_wallet_assignment($db, $walletEditorId, $assignmentId, (int)$adminUser['id'], $requestIp);
            $pageAlert = (string)($removeResult['message'] ?? '');
            $pageAlertType = !empty($removeResult['ok']) ? 'success' : 'danger';
        }
    }

    if (isset($_POST['admin_delete_crypto_wallet'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $walletEditorId = (int)($_POST['wallet_id'] ?? 0);
            $walletListPage = max(1, (int)($_POST['wallet_list_page'] ?? $walletListPage));
            $deleteResult = admin_delete_crypto_wallet($db, $walletEditorId, (int)$adminUser['id'], $requestIp);
            $pageAlert = (string)($deleteResult['message'] ?? admin_t($messages, 'wallet_delete_error', 'Unable to delete wallet.'));
            $pageAlertType = !empty($deleteResult['ok']) ? 'success' : 'danger';
            if (!empty($deleteResult['ok'])) {
                $walletEditorId = 0;
                $walletCreateMode = false;
            }
        }
    }

    if (isset($_POST['admin_split_crypto_wallet_conflict'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $walletEditorId = (int)($_POST['wallet_id'] ?? 0);
            $walletListPage = max(1, (int)($_POST['wallet_list_page'] ?? $walletListPage));
            $splitResult = admin_resolve_crypto_wallet_payment_conflict($db, $walletEditorId, (int)$adminUser['id'], $appSettings, $requestIp);
            $pageAlert = (string)($splitResult['message'] ?? '');
            $pageAlertType = !empty($splitResult['ok']) ? 'success' : 'danger';
        }
    }

    $walletAssetOptions = admin_crypto_asset_rows($db, $walletCreateMode);
    if ($walletCreateMode) {
        $walletAssetOptions = array_values(array_filter($walletAssetOptions, static function (array $assetRow): bool {
            return admin_crypto_asset_allows_customer_payments((string)($assetRow['code'] ?? ''));
        }));
    }
    $walletAssetSummaryRows = admin_crypto_wallet_asset_summary_rows($db);
    $walletAssetShortageCodes = [];
    foreach ($walletAssetSummaryRows as $walletAssetSummaryRow) {
        if ((int)($walletAssetSummaryRow['available_count'] ?? 0) <= 0) {
            $walletAssetShortageCodes[] = strtoupper(trim((string)($walletAssetSummaryRow['asset_code'] ?? '')));
        }
    }
    $walletAssetShortageCodes = array_values(array_filter(array_unique($walletAssetShortageCodes)));
    if ($walletCreateMode && !$walletAssetOptions) {
        $walletCreateMode = false;
        $pageAlert = admin_t($messages, 'wallet_create_no_active_assets', 'Activate a cryptocurrency first before adding a wallet address.');
        $pageAlertType = 'warning';
    }
    if ($cryptoWalletPoolDepleted) {
        $pageAlert = admin_t($messages, 'wallet_pool_empty_warning', 'No free crypto wallets are available right now. Add or release wallet addresses in the pool.');
        $pageAlertType = 'warning';
    }
    if ($walletFilterWalletId > 0) {
        $walletFilterWallet = admin_crypto_wallet_find($db, $walletFilterWalletId);
    }
    if ($walletEditorId > 0) {
        $walletEditor = admin_crypto_wallet_find($db, $walletEditorId);
        $walletAssignments = admin_crypto_wallet_active_assignments($db, $walletEditorId);
        $walletDeleteSummary = admin_crypto_wallet_delete_summary($db, $walletEditorId);
        $walletPaymentConflict = $cryptoWalletSharedEnabled
            ? ['can_split' => false, 'candidate' => null, 'keeper' => null, 'candidates' => []]
            : admin_crypto_wallet_payment_conflict_summary($db, $walletEditorId);
    } elseif ($walletCreateMode) {
        $walletEditor = [
            'id' => 0,
            'crypto_asset_id' => (int)($walletAssetOptions[0]['id'] ?? 0),
            'label' => '',
            'owner_full_name' => '',
            'address' => '',
            'network_code' => '',
            'memo_tag' => '',
            'wallet_provider' => '',
            'status' => 'available',
            'notes' => '',
            'asset_code' => (string)($walletAssetOptions[0]['code'] ?? ''),
            'asset_name' => (string)($walletAssetOptions[0]['name'] ?? ''),
        ];
    }
}

if ($route === 'bank-accounts') {
    $bankAccountEditorId = isset($_GET['edit_account']) ? (int)$_GET['edit_account'] : 0;
    $bankAccountCreateMode = isset($_GET['create_account']) && (int)$_GET['create_account'] === 1;
    $bankAccountTab = strtolower(trim((string)($_GET['bank_tab'] ?? 'accounts')));
    if (!in_array($bankAccountTab, ['accounts', 'stats'], true)) {
        $bankAccountTab = 'accounts';
    }
    $bankAccountListPage = max(1, (int)($_GET['account_list_page'] ?? 1));
    $bankAccountListTotal = admin_bank_account_count($db);
    $bankAccountListTotalPages = max(1, (int)ceil($bankAccountListTotal / $bankAccountListPerPage));
    $bankAccountCurrencyOptions = admin_bank_account_currency_rows($db);
    if ($bankAccountListPage > $bankAccountListTotalPages) {
        $bankAccountListPage = $bankAccountListTotalPages;
    }

    if (isset($_POST['admin_save_bank_account'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $bankAccountEditorId = (int)($_POST['bank_account_id'] ?? 0);
            $bankAccountListPage = max(1, (int)($_POST['account_list_page'] ?? $bankAccountListPage));
            $saveResult = admin_save_bank_account($db, $bankAccountEditorId, $_POST, (int)$adminUser['id'], $requestIp);
            $pageAlert = (string)($saveResult['message'] ?? '');
            $pageAlertType = !empty($saveResult['ok']) ? 'success' : 'danger';
            if (!empty($saveResult['ok']) && !empty($saveResult['bank_account_id'])) {
                $bankAccountEditorId = (int)$saveResult['bank_account_id'];
                $bankAccountCreateMode = false;
            }
        }
    }

    if (isset($_POST['admin_assign_bank_account_customer'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $bankAccountEditorId = (int)($_POST['bank_account_id'] ?? 0);
            $bankAccountListPage = max(1, (int)($_POST['account_list_page'] ?? $bankAccountListPage));
            $assignCustomerId = (int)($_POST['assignment_customer_id'] ?? 0);
            $assignResult = admin_assign_bank_account_customer($db, $bankAccountEditorId, $assignCustomerId, (int)$adminUser['id'], $appSettings, $requestIp);
            $pageAlert = (string)($assignResult['message'] ?? '');
            $pageAlertType = !empty($assignResult['ok']) ? 'success' : 'danger';
        }
    }

    if (isset($_POST['admin_remove_bank_account_assignment'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $bankAccountEditorId = (int)($_POST['bank_account_id'] ?? 0);
            $bankAccountListPage = max(1, (int)($_POST['account_list_page'] ?? $bankAccountListPage));
            $assignmentId = (int)($_POST['admin_remove_bank_account_assignment'] ?? 0);
            $removeResult = admin_remove_bank_account_assignment($db, $bankAccountEditorId, $assignmentId, (int)$adminUser['id'], $requestIp);
            $pageAlert = (string)($removeResult['message'] ?? '');
            $pageAlertType = !empty($removeResult['ok']) ? 'success' : 'danger';
        }
    }

    if (isset($_POST['admin_delete_bank_account'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $bankAccountEditorId = (int)($_POST['bank_account_id'] ?? 0);
            $bankAccountListPage = max(1, (int)($_POST['account_list_page'] ?? $bankAccountListPage));
            $deleteResult = admin_delete_bank_account($db, $bankAccountEditorId, (int)$adminUser['id'], $requestIp);
            $pageAlert = (string)($deleteResult['message'] ?? admin_t($messages, 'bank_delete_error', 'Unable to delete bank account.'));
            $pageAlertType = !empty($deleteResult['ok']) ? 'success' : 'danger';
            if (!empty($deleteResult['ok'])) {
                $bankAccountEditorId = 0;
            }
        }
    }

    if ($bankAccountEditorId > 0) {
        $bankAccountEditor = admin_bank_account_find($db, $bankAccountEditorId);
        $bankAccountAssignments = admin_bank_account_active_assignments($db, $bankAccountEditorId);
        $bankAccountDeleteSummary = admin_bank_account_delete_summary($db, $bankAccountEditorId);
    } elseif ($bankAccountCreateMode) {
        $bankAccountEditor = [
            'id' => 0,
            'currency_id' => (int)($bankAccountCurrencyOptions[0]['id'] ?? 0),
            'currency_code' => (string)($bankAccountCurrencyOptions[0]['code'] ?? ''),
            'label' => '',
            'account_holder_name' => '',
            'bank_name' => '',
            'bank_address' => '',
            'country_code' => '',
            'iban' => '',
            'account_number' => '',
            'routing_number' => '',
            'swift_bic' => '',
            'payment_reference_template' => '',
            'transfer_instructions' => '',
            'monthly_limit_amount' => null,
            'status' => 'available',
            'notes' => '',
        ];
        $bankAccountAssignments = [];
        $bankAccountDeleteSummary = ['active_assignments_total' => 0, 'assignments_total' => 0, 'payments_total' => 0, 'can_delete' => false];
    }
}

if ($route === 'users') {
    $userQuickCreateProviderRows = admin_provider_visibility_option_rows($db);
    $userQuickCreateState = [
        'email' => trim((string)($_POST['quick_email'] ?? '')),
        'public_handle' => trim((string)($_POST['quick_public_handle'] ?? '')),
        'password' => (string)($_POST['quick_password'] ?? ''),
        'locale_code' => admin_normalize_locale((string)($_POST['quick_locale_code'] ?? 'pl')),
        'status' => strtolower(trim((string)($_POST['quick_status'] ?? 'active'))),
        'customer_type' => app_normalize_customer_type((string)($_POST['quick_customer_type'] ?? 'client')),
        'send_password_email' => isset($_POST['quick_send_password_email']) ? 1 : 0,
        'provider_visibility_form_present' => isset($_POST['provider_visibility_form_present']) ? 1 : 0,
        'visible_provider_ids' => array_map('intval', (array)($_POST['visible_provider_ids'] ?? array_map(static function (array $providerRow): int {
            return (int)($providerRow['id'] ?? 0);
        }, $userQuickCreateProviderRows))),
    ];
    $userImportState = [
        'source_text' => trim((string)($_POST['import_source_text'] ?? '')),
        'locale_code' => admin_normalize_locale((string)($_POST['import_locale_code'] ?? 'pl')),
        'status' => strtolower(trim((string)($_POST['import_status'] ?? 'active'))),
        'customer_type' => (string)($_POST['import_customer_type'] ?? 'client'),
        'send_password_email' => !array_key_exists('admin_import_customers', $_POST) || !empty($_POST['import_send_password_email']),
        'provider_visibility_form_present' => 1,
        'visible_provider_ids' => array_map('intval', (array)($_POST['visible_provider_ids'] ?? array_map(static function (array $providerRow): int {
            return (int)($providerRow['id'] ?? 0);
        }, $userQuickCreateProviderRows))),
    ];

    if (isset($_POST['admin_quick_create_customer'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $quickCreateResult = admin_create_customer_account(
                $db,
                (string)($userQuickCreateState['email'] ?? ''),
                (string)($userQuickCreateState['password'] ?? ''),
                [
                    'public_handle' => (string)($userQuickCreateState['public_handle'] ?? ''),
                    'locale_code' => (string)($userQuickCreateState['locale_code'] ?? 'pl'),
                    'status' => (string)($userQuickCreateState['status'] ?? 'active'),
                    'customer_type' => (string)($userQuickCreateState['customer_type'] ?? 'client'),
                    'send_password_email' => !empty($userQuickCreateState['send_password_email']),
                    'provider_visibility_form_present' => !empty($userQuickCreateState['provider_visibility_form_present']) ? 1 : 0,
                    'visible_provider_ids' => (array)($userQuickCreateState['visible_provider_ids'] ?? []),
                ],
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );
            $pageAlertType = !empty($quickCreateResult['ok']) ? 'success' : 'danger';
            if (!empty($quickCreateResult['ok'])) {
                $pageAlert = admin_t($messages, 'users_quick_add_success', 'User created successfully.')
                    . ' Email: ' . (string)($quickCreateResult['email'] ?? '')
                    . ' Password: ' . (string)($quickCreateResult['password'] ?? '') . '.';
                $pageAlertHtml = admin_e(admin_t($messages, 'users_quick_add_success', 'User created successfully.'))
                    . ' Email: <strong>' . admin_e((string)($quickCreateResult['email'] ?? '')) . '</strong>'
                    . ' Password: <strong>' . admin_e((string)($quickCreateResult['password'] ?? '')) . '</strong>.';
                if (!empty($userQuickCreateState['send_password_email'])) {
                    $emailNotificationText = $adminPasswordEmailNotice($messages, (array)($quickCreateResult['email_notification'] ?? []));
                    $pageAlert .= ' ' . $emailNotificationText;
                    $pageAlertHtml .= ' ' . admin_e($emailNotificationText);
                }
                $userQuickCreateState = [
                    'email' => '',
                    'public_handle' => '',
                    'password' => '',
                    'locale_code' => admin_normalize_locale((string)($userQuickCreateState['locale_code'] ?? 'pl')),
                    'status' => strtolower(trim((string)($userQuickCreateState['status'] ?? 'active'))),
                    'customer_type' => 'client',
                    'send_password_email' => 1,
                    'provider_visibility_form_present' => 1,
                    'visible_provider_ids' => array_map(static function (array $providerRow): int {
                        return (int)($providerRow['id'] ?? 0);
                    }, $userQuickCreateProviderRows),
                ];
            } else {
                $pageAlert = (string)($quickCreateResult['message'] ?? '');
            }
        }
    }

    if (isset($_POST['admin_import_customers'])) {
        $importSourceText = trim((string)($_POST['import_source_text'] ?? ''));
        if ($importSourceText === '' && !empty($_FILES['import_source_file']['tmp_name']) && is_uploaded_file($_FILES['import_source_file']['tmp_name'])) {
            $importSourceText = (string)file_get_contents($_FILES['import_source_file']['tmp_name']);
        }
        $userImportState['source_text'] = $importSourceText;

        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $importResult = admin_import_customer_accounts(
                $db,
                $importSourceText,
                [
                    'locale_code' => (string)($userImportState['locale_code'] ?? 'pl'),
                    'status' => (string)($userImportState['status'] ?? 'active'),
                    'customer_type' => (string)($userImportState['customer_type'] ?? 'client'),
                    'send_password_email' => !empty($userImportState['send_password_email']),
                    'provider_visibility_form_present' => !empty($userImportState['provider_visibility_form_present']) ? 1 : 0,
                    'visible_provider_ids' => (array)($userImportState['visible_provider_ids'] ?? []),
                ],
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );
            $pageAlert = (string)($importResult['message'] ?? '');
            $pageAlertType = !empty($importResult['ok']) ? 'success' : 'danger';
            if (!empty($importResult['ok'])) {
                $userImportState['source_text'] = '';
            }
        }
    }

    $selectedCustomerId = isset($_GET['customer_id'])
        ? (int)$_GET['customer_id']
        : (isset($_POST['customer_id']) ? (int)$_POST['customer_id'] : 0);
    if ($selectedCustomerId > 0 && isset($_POST['admin_save_customer_profile'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $saveResult = admin_save_customer_profile(
                $db,
                $selectedCustomerId,
                $_POST,
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );
            $pageAlert = (string)($saveResult['message'] ?? '');
            $pageAlertType = !empty($saveResult['ok']) ? 'success' : 'danger';
        }
    }

    if ($selectedCustomerId > 0 && isset($_POST['admin_adjust_customer_balance'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $balanceResult = admin_adjust_customer_balance(
                $db,
                $selectedCustomerId,
                $_POST,
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );
            $pageAlert = (string)($balanceResult['message'] ?? '');
            $pageAlertType = !empty($balanceResult['ok']) ? 'success' : 'danger';
        }
    }

    if (
        $selectedCustomerId > 0
        && (isset($_POST['admin_set_customer_password']) || isset($_POST['admin_resend_customer_password']))
    ) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $passwordPayload = $_POST;
            if (isset($_POST['admin_resend_customer_password'])) {
                $passwordPayload['send_password_email'] = '1';
            }

            $passwordResult = admin_set_customer_password(
                $db,
                $selectedCustomerId,
                $passwordPayload,
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );
            $passwordMessageKey = trim((string)($passwordResult['message_key'] ?? ''));
            $pageAlert = $passwordMessageKey !== ''
                ? admin_t($messages, $passwordMessageKey, (string)($passwordResult['message'] ?? ''))
                : (string)($passwordResult['message'] ?? '');
            $pageAlertType = (string)($passwordResult['alert_type'] ?? (!empty($passwordResult['ok']) ? 'success' : 'danger'));
        }
    }

    if ($selectedCustomerId > 0 && isset($_POST['admin_delete_customer'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $deleteCustomerResult = admin_delete_customer_account(
                $db,
                $selectedCustomerId,
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );

            if (!empty($deleteCustomerResult['ok'])) {
                header('Location: /admin/?page=users&deleted_user=1');
                exit;
            }

            $pageAlert = (string)($deleteCustomerResult['message'] ?? '');
            $pageAlertType = 'danger';
        }
    }

    if ($selectedCustomerId > 0 && isset($_POST['admin_delete_customer_wallet_assignment'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $deleteWalletResult = admin_delete_customer_wallet_assignment(
                $db,
                $selectedCustomerId,
                (int)($_POST['wallet_assignment_id'] ?? 0),
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );
            $pageAlert = (string)($deleteWalletResult['message'] ?? admin_t($messages, 'customer_wallet_delete_error', 'Unable to remove wallet assignment.'));
            $pageAlertType = !empty($deleteWalletResult['ok']) ? 'success' : 'danger';
        }
    }

    if ($selectedCustomerId > 0 && isset($_POST['admin_delete_customer_bank_assignment'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $deleteBankResult = admin_delete_customer_bank_assignment(
                $db,
                $selectedCustomerId,
                (int)($_POST['bank_account_assignment_id'] ?? 0),
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );
            $pageAlert = (string)($deleteBankResult['message'] ?? admin_t($messages, 'customer_bank_delete_error', 'Unable to remove bank account assignment.'));
            $pageAlertType = !empty($deleteBankResult['ok']) ? 'success' : 'danger';
        }
    }

    if ($selectedCustomerId > 0 && isset($_POST['admin_delete_customer_activity_entry'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $deleteActivityResult = admin_delete_customer_activity_entry(
                $db,
                $selectedCustomerId,
                (int)($_POST['activity_id'] ?? 0),
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );
            $pageAlert = (string)($deleteActivityResult['message'] ?? admin_t($messages, 'customer_activity_delete_error', 'Unable to remove history entry.'));
            $pageAlertType = !empty($deleteActivityResult['ok']) ? 'success' : 'danger';
        }
    }

    if ($selectedCustomerId > 0 && isset($_POST['admin_customer_group_invite_action'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $groupInviteResult = admin_customer_group_chat_invite_response(
                $db,
                $selectedCustomerId,
                (int)($_POST['conversation_id'] ?? 0),
                (string)($_POST['invite_decision'] ?? ''),
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );
            $pageAlert = (string)($groupInviteResult['message'] ?? admin_t($messages, 'customer_group_chat_action_error', 'Unable to update the group invitation.'));
            $pageAlertType = !empty($groupInviteResult['ok']) ? 'success' : 'danger';
        }
    }

    if ($selectedCustomerId > 0 && isset($_POST['admin_customer_leave_group_chat'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $leaveGroupResult = admin_customer_leave_group_chat(
                $db,
                $selectedCustomerId,
                (int)($_POST['conversation_id'] ?? 0),
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );
            $pageAlert = (string)($leaveGroupResult['message'] ?? admin_t($messages, 'customer_group_chat_leave_error', 'Unable to leave the group chat.'));
            $pageAlertType = !empty($leaveGroupResult['ok']) ? 'success' : 'danger';
        }
    }

    if ($selectedCustomerId > 0 && isset($_POST['admin_customer_delete_group_chat'])) {
        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $deleteGroupResult = admin_customer_delete_group_chat(
                $db,
                $selectedCustomerId,
                (int)($_POST['conversation_id'] ?? 0),
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );
            $pageAlert = (string)($deleteGroupResult['message'] ?? admin_t($messages, 'customer_group_chat_delete_error', 'Unable to delete the group chat.'));
            $pageAlertType = !empty($deleteGroupResult['ok']) ? 'success' : 'danger';
        }
    }

    if ($selectedCustomerId > 0) {
        $selectedCustomer = admin_customer_detail_row($db, $selectedCustomerId);
        if ($selectedCustomer) {
            $selectedCustomerSummary = admin_customer_management_summary($db, $selectedCustomerId);
            $selectedCustomerOrders = admin_customer_order_rows($db, $selectedCustomerId);
            $selectedCustomerPayments = admin_customer_payment_activity($db, $selectedCustomerId);
            $selectedCustomerGroupChats = admin_customer_group_chat_rows($db, $selectedCustomerId);
            $selectedCustomerProviderVisibility = admin_customer_provider_visibility_rows($db, $selectedCustomerId);
            $selectedCustomerWallets = admin_customer_wallet_rows($db, $selectedCustomerId);
            $selectedCustomerBankAccounts = admin_customer_bank_rows($db, $selectedCustomerId);
            $selectedCustomerActivity = admin_customer_activity_rows($db, $selectedCustomerId);

            if ((int)($selectedCustomerSummary['orders_total'] ?? 0) === 0) {
                $userQuickOrderVisibleProviderIds = admin_customer_visible_provider_ids($db, $selectedCustomerId);
                $userQuickOrderProviders = array_values(array_filter(
                    admin_product_provider_rows($db),
                    static function (array $providerRow) use ($userQuickOrderVisibleProviderIds): bool {
                        $providerId = (int)($providerRow['id'] ?? 0);
                        return $providerId > 0 && in_array($providerId, $userQuickOrderVisibleProviderIds, true);
                    }
                ));
                $userQuickOrderProducts = array_values(array_filter(
                    admin_product_active_rows($db),
                    static function (array $productRow) use ($userQuickOrderVisibleProviderIds): bool {
                        $providerId = (int)($productRow['provider_id'] ?? 0);
                        return $providerId > 0
                            && in_array($providerId, $userQuickOrderVisibleProviderIds, true)
                            && admin_order_product_can_extend($productRow);
                    }
                ));
                foreach ($userQuickOrderProducts as $userQuickOrderProduct) {
                    $providerId = (int)($userQuickOrderProduct['provider_id'] ?? 0);
                    if ($providerId <= 0) {
                        continue;
                    }
                    if (!isset($userQuickOrderProductsByProvider[$providerId])) {
                        $userQuickOrderProductsByProvider[$providerId] = [];
                    }
                    $userQuickOrderProductsByProvider[$providerId][] = $userQuickOrderProduct;
                }
                $userQuickOrderAvailable = !empty($userQuickOrderProviders) && !empty($userQuickOrderProducts);
            }
        }
    }

    if (isset($_POST['admin_create_user_quick_order']) && $selectedCustomerId > 0) {
        $userQuickOrderState = [
            'provider_id' => (int)($_POST['provider_id'] ?? 0),
            'product_id' => (int)($_POST['product_id'] ?? 0),
            'customer_note' => trim((string)($_POST['customer_note'] ?? '')),
        ];

        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } elseif (!$selectedCustomer || (int)($selectedCustomerSummary['orders_total'] ?? 0) > 0 || !$userQuickOrderAvailable) {
            $pageAlert = admin_t($messages, 'order_create_error', 'Unable to create order.');
            $pageAlertType = 'danger';
        } else {
            $createResult = admin_create_order($db, [
                'customer_id' => $selectedCustomerId,
                'product_id' => $userQuickOrderState['product_id'],
                'customer_note' => $userQuickOrderState['customer_note'],
                'has_delivery_link' => '0',
                'delivery_link' => '',
            ]);

            if (!empty($createResult['ok'])) {
                header('Location: /admin/?page=users&customer_id=' . $selectedCustomerId . '&created_order=1');
                exit;
            }

            $pageAlert = (string)($createResult['message'] ?? admin_t($messages, 'order_create_error', 'Unable to create order.'));
            $pageAlertType = 'danger';
        }
    }
}

if ($route === 'payments') {
    $cryptoPaymentsVisibleInPayments = !empty($appSettings['crypto_payments_enabled']);
    $bankTransfersVisibleInPayments = admin_bank_transfers_enabled($appSettings);
    $paymentFilterCustomerId = isset($_GET['customer_id']) ? (int)$_GET['customer_id'] : 0;
    if ($paymentFilterCustomerId > 0) {
        $paymentFilterCustomer = admin_customer_basic_row($db, $paymentFilterCustomerId);
        if (!$paymentFilterCustomer) {
            $paymentFilterCustomerId = 0;
        }
    }

    $paymentScope = strtolower(trim((string)($_GET['payment_scope'] ?? 'open')));
    if (!in_array($paymentScope, ['open', 'new', 'review', 'approved', 'archived', 'expired', 'cancelled', 'all'], true)) {
        $paymentScope = 'open';
    }

    $paymentTypeFilter = strtolower(trim((string)($_GET['payment_type_filter'] ?? '')));
    if (!in_array($paymentTypeFilter, ['', 'crypto', 'bank'], true)) {
        $paymentTypeFilter = '';
    }
    if (!$cryptoPaymentsVisibleInPayments && $paymentTypeFilter === 'crypto') {
        $paymentTypeFilter = '';
    }
    if (!$bankTransfersVisibleInPayments && $paymentTypeFilter === 'bank') {
        $paymentTypeFilter = '';
    }

    $buildPaymentsListUrl = static function (array $overrides = []) use ($paymentFilterCustomerId, $paymentScope, $paymentTypeFilter): string {
        $query = [
            'page' => 'payments',
            'customer_id' => $paymentFilterCustomerId > 0 ? $paymentFilterCustomerId : null,
            'payment_scope' => $paymentScope,
            'payment_type_filter' => $paymentTypeFilter !== '' ? $paymentTypeFilter : null,
        ];

        foreach ($overrides as $key => $value) {
            $query[$key] = $value;
        }

        foreach ($query as $key => $value) {
            if ($value === null || $value === '') {
                unset($query[$key]);
            }
        }

        return '/admin/?' . http_build_query($query);
    };

    $paymentEditorType = strtolower(trim((string)($_GET['payment_type'] ?? '')));
    if (!in_array($paymentEditorType, ['crypto', 'crypto_topup', 'bank'], true)) {
        $paymentEditorType = '';
    }
    if (!$bankTransfersVisibleInPayments && $paymentEditorType === 'bank') {
        $paymentEditorType = '';
    }
    $paymentEditorId = isset($_GET['payment_id']) ? (int)$_GET['payment_id'] : 0;

    if (isset($_POST['admin_payment_quick_action_ajax'])) {
        header('Content-Type: application/json; charset=utf-8');

        $paymentEditorType = strtolower(trim((string)($_POST['payment_type'] ?? $paymentEditorType)));
        if (!in_array($paymentEditorType, ['crypto', 'crypto_topup', 'bank'], true)) {
            $paymentEditorType = '';
        }
        if (!$bankTransfersVisibleInPayments && $paymentEditorType === 'bank') {
            $paymentEditorType = '';
        }
        $paymentEditorId = (int)($_POST['payment_id'] ?? $paymentEditorId);

        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            http_response_code(403);
            echo json_encode([
                'ok' => false,
                'message' => admin_t($messages, 'login_error', 'Login failed. Check your credentials.'),
            ]);
            exit;
        }

        if ($paymentEditorType === '') {
            http_response_code(422);
            echo json_encode([
                'ok' => false,
                'message' => admin_t($messages, 'payment_bank_disabled_hidden', 'Bank transfer payments are currently hidden.'),
            ]);
            exit;
        }

        $quickActionResult = admin_payment_apply_quick_action(
            $db,
            $paymentEditorType,
            $paymentEditorId,
            (string)($_POST['quick_action'] ?? ''),
            (int)($adminUser['id'] ?? 0),
            $requestIp,
            $_POST
        );

        if (empty($quickActionResult['ok'])) {
            http_response_code(422);
            echo json_encode([
                'ok' => false,
                'message' => (string)($quickActionResult['message'] ?? admin_t($messages, 'payment_save_error', 'Unable to save payment request.')),
            ]);
            exit;
        }

        $orderPayload = null;
        $acceptedOrderId = (int)($quickActionResult['order_id'] ?? 0);
        $acceptedCustomerId = (int)($quickActionResult['customer_id'] ?? 0);
        if ($acceptedOrderId > 0) {
            $acceptedOrderRow = admin_topbar_notification_order_row_by_id($db, $acceptedOrderId);
            if (is_array($acceptedOrderRow)) {
                $acceptedOrderStatusVisual = admin_order_status_visual($acceptedOrderRow);
                $acceptedOrderHandle = trim((string)($acceptedOrderRow['public_handle'] ?? ''));
                $acceptedOrderPaymentType = (int)($acceptedOrderRow['crypto_payment_id'] ?? 0) > 0
                    ? 'crypto'
                    : ((int)($acceptedOrderRow['bank_payment_id'] ?? 0) > 0 ? 'bank' : '');
                $acceptedOrderPaymentId = $acceptedOrderPaymentType === 'crypto'
                    ? (int)($acceptedOrderRow['crypto_payment_id'] ?? 0)
                    : (int)($acceptedOrderRow['bank_payment_id'] ?? 0);
                $acceptedOrderWalletAddress = trim((string)($acceptedOrderRow['wallet_address'] ?? ''));
                $acceptedOrderWalletLabel = trim((string)($acceptedOrderRow['wallet_label'] ?? ''));
                $acceptedOrderWalletAssetCode = trim((string)($acceptedOrderRow['wallet_asset_code'] ?? ''));
                $acceptedOrderWalletNetworkCode = trim((string)($acceptedOrderRow['wallet_network_code'] ?? ''));
                $orderPayload = [
                    'id' => $acceptedOrderId,
                    'customer_id' => (int)($acceptedOrderRow['customer_id'] ?? 0),
                    'customer_email' => (string)($acceptedOrderRow['customer_email'] ?? ''),
                    'customer_handle' => $acceptedOrderHandle,
                    'order_url' => '/admin/?page=orders&order_id=' . $acceptedOrderId,
                    'payment_url' => ($acceptedOrderPaymentType !== '' && $acceptedOrderPaymentId > 0)
                        ? '/admin/?page=payments&payment_type=' . rawurlencode($acceptedOrderPaymentType) . '&payment_id=' . $acceptedOrderPaymentId
                        : '',
                    'status_icon' => (string)($acceptedOrderStatusVisual['icon'] ?? 'bi bi-arrow-repeat'),
                    'status_class' => (string)($acceptedOrderStatusVisual['class'] ?? 'admin-order-status-icon--awaiting-activation'),
                    'wallet_address_compact' => $acceptedOrderWalletAddress !== '' ? admin_compact_wallet_address($acceptedOrderWalletAddress, 8, 5) : '',
                    'wallet_explorer_url' => $acceptedOrderWalletAddress !== '' ? admin_crypto_wallet_explorer_url($acceptedOrderWalletAssetCode, $acceptedOrderWalletNetworkCode, $acceptedOrderWalletAddress) : '',
                    'wallet_label' => $acceptedOrderWalletLabel,
                    'task_html' => admin_topbar_order_tasks_html([$acceptedOrderRow], 1, $messages),
                ];
            } else {
                $fallbackOrderRow = admin_order_find($db, $acceptedOrderId);
                if (is_array($fallbackOrderRow)) {
                    $fallbackOrderStatusVisual = admin_order_status_visual($fallbackOrderRow);
                    $acceptedOrderHandle = trim((string)($fallbackOrderRow['public_handle'] ?? ''));
                    $orderPayload = [
                        'id' => $acceptedOrderId,
                        'customer_id' => (int)($fallbackOrderRow['customer_id'] ?? 0),
                        'customer_email' => (string)($fallbackOrderRow['customer_email'] ?? ''),
                        'customer_handle' => $acceptedOrderHandle,
                        'order_url' => '/admin/?page=orders&order_id=' . $acceptedOrderId,
                        'payment_url' => '',
                        'status_icon' => (string)($fallbackOrderStatusVisual['icon'] ?? 'bi bi-arrow-repeat'),
                        'status_class' => (string)($fallbackOrderStatusVisual['class'] ?? 'admin-order-status-icon--awaiting-activation'),
                        'wallet_address_compact' => '',
                        'wallet_explorer_url' => '',
                        'wallet_label' => '',
                    ];
                }
            }
        }

        $redirectUrl = '/admin/?page=orders';
        if ($acceptedOrderId > 0) {
            $redirectUrl = '/admin/?page=orders&order_id=' . $acceptedOrderId;
        } elseif ($acceptedCustomerId > 0) {
            $redirectUrl = '/admin/?page=orders&customer_id=' . $acceptedCustomerId;
        }

        $cryptoQuickView = null;
        if (!empty($_POST['crypto_quick_inline']) && $paymentEditorType === 'crypto') {
            require_once __DIR__ . '/crypto_quick.php';
            $cryptoQuickFilter = (string)($_POST['crypto_quick_filter'] ?? 'new');
            if (in_array($cryptoQuickFilter, ['new', 'expired', 'cancelled', 'payout'], true)) {
                try {
                    $cryptoQuickView = [
                        'filter' => $cryptoQuickFilter,
                        'counts' => admin_crypto_quick_counts($db),
                        'html' => admin_crypto_quick_html(admin_crypto_quick_rows($db, $cryptoQuickFilter), $cryptoQuickFilter, admin_crypto_quick_labels(), admin_csrf_token(), $messages),
                    ];
                } catch (Throwable $e) {
                    // The action succeeded; the flyout can retry its read independently.
                }
            }
        }

        $cryptoReminderView = null;
        if (!empty($_POST['crypto_reminder_inline']) && !empty($_POST['crypto_quick_inline']) && $paymentEditorType === 'crypto') {
            try { $cryptoReminderView = admin_crypto_reminder_view($db, admin_csrf_token(), $messages, $cryptoQuickView['counts'] ?? null, $currentLocale); }
            catch (Throwable $e) { /* The action is saved; the reminder can retry its read. */ }
        }

        echo json_encode([
            'ok' => true,
            'message' => (string)($quickActionResult['message'] ?? admin_t($messages, 'payment_save_success', 'Payment request saved successfully.')),
            'crypto_quick' => $cryptoQuickView,
            'crypto_reminder' => $cryptoReminderView,
            'payment_id' => $paymentEditorId,
            'order' => $orderPayload,
            'redirect_url' => $redirectUrl,
        ], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE);
        exit;
    }

    if (isset($_POST['admin_payment_quick_action'])) {
        $paymentEditorType = strtolower(trim((string)($_POST['payment_type'] ?? $paymentEditorType)));
        if (!in_array($paymentEditorType, ['crypto', 'crypto_topup', 'bank'], true)) {
            $paymentEditorType = '';
        }
        if (!$bankTransfersVisibleInPayments && $paymentEditorType === 'bank') {
            $paymentEditorType = '';
        }
        $paymentEditorId = (int)($_POST['payment_id'] ?? $paymentEditorId);
        $paymentFilterCustomerId = max(0, (int)($_POST['customer_id'] ?? $paymentFilterCustomerId));
        $paymentScope = strtolower(trim((string)($_POST['payment_scope'] ?? $paymentScope)));
        if (!in_array($paymentScope, ['open', 'new', 'review', 'approved', 'archived', 'expired', 'cancelled', 'all'], true)) {
            $paymentScope = 'open';
        }
        $paymentTypeFilter = strtolower(trim((string)($_POST['payment_type_filter'] ?? $paymentTypeFilter)));
        if (!in_array($paymentTypeFilter, ['', 'crypto', 'bank'], true)) {
            $paymentTypeFilter = '';
        }
        if (!$cryptoPaymentsVisibleInPayments && $paymentTypeFilter === 'crypto') {
            $paymentTypeFilter = '';
        }
        if (!$bankTransfersVisibleInPayments && $paymentTypeFilter === 'bank') {
            $paymentTypeFilter = '';
        }

        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } elseif ($paymentEditorType === '') {
            $pageAlert = admin_t($messages, 'payment_bank_disabled_hidden', 'Bank transfer payments are currently hidden.');
            $pageAlertType = 'danger';
        } else {
            $quickActionResult = admin_payment_apply_quick_action(
                $db,
                $paymentEditorType,
                $paymentEditorId,
                (string)($_POST['quick_action'] ?? ''),
                (int)($adminUser['id'] ?? 0),
                $requestIp,
                $_POST
            );

            if (!empty($quickActionResult['ok'])) {
                $quickAction = strtolower(trim((string)($_POST['quick_action'] ?? '')));
                if ($quickAction === 'accept') {
                    $acceptedOrderId = (int)($quickActionResult['order_id'] ?? 0);
                    $acceptedCustomerId = (int)($quickActionResult['customer_id'] ?? 0);
                    if ($acceptedOrderId > 0) {
                        $redirectUrl = '/admin/?page=orders&order_id=' . $acceptedOrderId;
                    } elseif ($acceptedCustomerId > 0) {
                        $redirectUrl = '/admin/?page=orders&customer_id=' . $acceptedCustomerId;
                    } else {
                        $redirectUrl = '/admin/?page=orders';
                    }
                } elseif ($quickAction === 'renew' && !empty($quickActionResult['payment_type']) && (int)($quickActionResult['payment_id'] ?? 0) > 0) {
                    $redirectUrl = '/admin/?page=payments&payment_type=' . rawurlencode((string)$quickActionResult['payment_type']) . '&payment_id=' . (int)$quickActionResult['payment_id'] . '&renewed_payment=1';
                } else {
                    $redirectUrl = trim((string)($_POST['redirect_to'] ?? ''));
                    if ($redirectUrl === '') {
                        $redirectScope = $quickAction === 'archive'
                            ? 'archived'
                            : ($quickAction === 'renew' ? 'open' : ($quickAction === 'cancel' ? 'cancelled' : $paymentScope));
                        $redirectUrl = $buildPaymentsListUrl([
                            $quickAction === 'delete' ? 'deleted_payment' : 'saved_payment' => 1,
                            'payment_scope' => $redirectScope !== 'all' ? $redirectScope : null,
                        ]);
                    }
                }
                header('Location: ' . $redirectUrl);
                exit;
            }

            $pageAlert = (string)($quickActionResult['message'] ?? admin_t($messages, 'payment_save_error', 'Unable to save payment request.'));
            $pageAlertType = 'danger';
        }
    }

    if (isset($_POST['admin_save_payment'])) {
        $paymentEditorType = strtolower(trim((string)($_POST['payment_type'] ?? $paymentEditorType)));
        if (!in_array($paymentEditorType, ['crypto', 'crypto_topup', 'bank'], true)) {
            $paymentEditorType = '';
        }
        if (!$bankTransfersVisibleInPayments && $paymentEditorType === 'bank') {
            $paymentEditorType = '';
        }
        $paymentEditorId = (int)($_POST['payment_id'] ?? $paymentEditorId);
        $paymentFilterCustomerId = max(0, (int)($_POST['customer_id'] ?? $paymentFilterCustomerId));

        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } elseif ($paymentEditorType === '') {
            $pageAlert = admin_t($messages, 'payment_bank_disabled_hidden', 'Bank transfer payments are currently hidden.');
            $pageAlertType = 'danger';
        } else {
            $saveResult = admin_save_payment($db, $paymentEditorType, $paymentEditorId, $_POST, (int)($adminUser['id'] ?? 0), $requestIp);
            if (!empty($saveResult['ok'])) {
                $redirect = $buildPaymentsListUrl([
                    'payment_type' => $paymentEditorType,
                    'payment_id' => $paymentEditorId,
                    'saved_payment' => 1,
                ]);
                header('Location: ' . $redirect);
                exit;
            }

            $pageAlert = (string)($saveResult['message'] ?? admin_t($messages, 'payment_save_error', 'Unable to save payment request.'));
            $pageAlertType = 'danger';
        }
    }

    if (isset($_POST['admin_delete_payment'])) {
        $paymentEditorType = strtolower(trim((string)($_POST['payment_type'] ?? $paymentEditorType)));
        if (!in_array($paymentEditorType, ['crypto', 'crypto_topup', 'bank'], true)) {
            $paymentEditorType = '';
        }
        if (!$bankTransfersVisibleInPayments && $paymentEditorType === 'bank') {
            $paymentEditorType = '';
        }
        $paymentEditorId = (int)($_POST['payment_id'] ?? $paymentEditorId);
        $paymentFilterCustomerId = max(0, (int)($_POST['customer_id'] ?? $paymentFilterCustomerId));

        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } elseif ($paymentEditorType === '') {
            $pageAlert = admin_t($messages, 'payment_bank_disabled_hidden', 'Bank transfer payments are currently hidden.');
            $pageAlertType = 'danger';
        } else {
            $deleteResult = admin_delete_payment($db, $paymentEditorType, $paymentEditorId, (int)($adminUser['id'] ?? 0), $requestIp);
            if (!empty($deleteResult['ok'])) {
                $redirect = $buildPaymentsListUrl(['deleted_payment' => 1]);
                header('Location: ' . $redirect);
                exit;
            }

            $pageAlert = (string)($deleteResult['message'] ?? admin_t($messages, 'payment_delete_error', 'Unable to delete payment request.'));
            $pageAlertType = 'danger';
        }
    }

    if (isset($_POST['admin_delete_cancelled_payments'])) {
        $paymentFilterCustomerId = max(0, (int)($_POST['customer_id'] ?? $paymentFilterCustomerId));
        $paymentScope = strtolower(trim((string)($_POST['payment_scope'] ?? $paymentScope)));
        if (!in_array($paymentScope, ['open', 'new', 'review', 'approved', 'archived', 'expired', 'cancelled', 'all'], true)) {
            $paymentScope = 'open';
        }
        $paymentTypeFilter = strtolower(trim((string)($_POST['payment_type_filter'] ?? $paymentTypeFilter)));
        if (!in_array($paymentTypeFilter, ['', 'crypto', 'bank'], true)) {
            $paymentTypeFilter = '';
        }
        if (!$cryptoPaymentsVisibleInPayments && $paymentTypeFilter === 'crypto') {
            $paymentTypeFilter = '';
        }
        if (!$bankTransfersVisibleInPayments && $paymentTypeFilter === 'bank') {
            $paymentTypeFilter = '';
        }

        if (!admin_csrf_is_valid($_POST['_csrf'] ?? '')) {
            $pageAlert = admin_t($messages, 'login_error', 'Login failed. Check your credentials.');
            $pageAlertType = 'danger';
        } else {
            $deleteCancelledResult = admin_delete_cancelled_payments(
                $db,
                $paymentFilterCustomerId,
                $paymentTypeFilter,
                $bankTransfersVisibleInPayments,
                (int)($adminUser['id'] ?? 0),
                $requestIp
            );
            if (!empty($deleteCancelledResult['ok'])) {
                header('Location: ' . $buildPaymentsListUrl([
                    'deleted_cancelled_payments' => (int)($deleteCancelledResult['deleted_total'] ?? 0),
                ]));
                exit;
            }

            $pageAlert = (string)($deleteCancelledResult['message'] ?? admin_t($messages, 'payment_delete_error', 'Unable to delete payment request.'));
            $pageAlertType = 'danger';
        }
    }

    if ($paymentEditorType !== '' && $paymentEditorId > 0) {
        $paymentEditor = admin_payment_find($db, $paymentEditorType, $paymentEditorId);
        if (!$paymentEditor) {
            $paymentEditorType = '';
            $paymentEditorId = 0;
        } elseif (isset($_POST['admin_save_payment'])) {
            $paymentEditor = array_merge($paymentEditor, $_POST);
        }
    }
}

