$chatPendingGroupInvites = admin_chat_group_pending_invites($db, (int)($adminUser['id'] ?? 0));
$chatInboxEntries = [];
$chatOnlineCount = 0;
$chatActiveCount = 0;

foreach ($chatInboxRows as $chatRow) {
