                                        $escaped = admin_e($text);
                                        $terms = [
                                            'BNB Smart Chain',
                                            'Ethereum ERC-20',
                                            'Ethereum/ERC-20',
                                            'USDT ERC-20',
                                            'Send to wallet',
                                            'Get BSC gas',
                                            'assetu B',
                                            'asset B',
