                                            'Dogecoin',
                                            'Bitcoina',
                                            'Bitcoin',
                                            'Polygon',
                                            'Solana',
                                            'USDT',
                                            'DOGE',
                                            'BSC',
                                            'ETH',
                                            'BNB',
                                            'SOL',
                                            'POL',
                                            'MATIC',
                                        ];
                                        $pattern = '/(?<![\\p{L}\\p{N}])(' . implode('|', array_map(static fn ($term) => preg_quote($term, '/'), $terms)) . ')(?![\\p{L}\\p{N}])/u';
