                                                                        ? admin_t($messages, 'payment_stage_success', 'Success')
                                                                        : (in_array($paymentStatus, ['pending', 'pending_payment'], true)
                                                                            ? admin_t($messages, 'payment_stage_new', 'New')
                                                                            : admin_t($messages, 'payment_filter_open', 'Open')))));
