                                                                if ($paymentCryptoAmountLabel === '') {
                                                                    $paymentCryptoAmountLabel = '0';
                                                                }
                                                                if ($paymentAssetCode !== '') {
                                                                    $paymentCryptoAmountLabel .= ' ' . strtoupper($paymentAssetCode);
                                                                }
                                                            }
                                                            $paymentDetailsUrl = $buildPaymentsListUrl([
                                                                'payment_type' => $paymentType,
