                    if (!integrator) {
                        mount.innerHTML = '<div class="alert alert-warning mb-0"><?php echo admin_e(admin_t($messages, 'swap_converter_widget_missing_integrator', 'LI.FI integrator name is missing. Fill it in Settings (admin mode).')); ?></div>';
